class MagixHeroSlider{constructor(e){this.sliderElement=document.getElementById(e),this.sliderElement&&"undefined"!=typeof Splide&&this.init()}init(){new Splide(this.sliderElement,{type:"fade",rewind:!0,autoplay:!0,interval:6e3,pauseOnHover:!1,arrows:!0,pagination:!0,speed:1e3,heightRatio:.4,breakpoints:{992:{heightRatio:.586},576:{heightRatio:.667,arrows:!1}}}).mount()}}document.addEventListener("DOMContentLoaded",(()=>{new MagixHeroSlider("magix-hero-slideshow")}));